xpath.script:
document.addEventListener('DOMContentLoaded', function () {
    var courseSelect = document.getElementById('course_id');
    var partGroup = document.getElementById('irg_practice_part_group');
    var partSelect = document.getElementById('irg_practice_part');
    var partHint = document.getElementById('irg_practice_part2_hint');
    if (!courseSelect || !partGroup || !partSelect) {
        return;
    }
    function syncPracticePart() {
        var option = courseSelect.options[courseSelect.selectedIndex];
        var isNc = option && option.getAttribute('data-irg-nc') === '1';
        var part2Ok = option && option.getAttribute('data-irg-part2') === '1';
        partGroup.hidden = !isNc;
        partSelect.required = !!isNc;
        var part2Option = partSelect.querySelector('option[value="2"]');
        if (part2Option) {
            part2Option.disabled = isNc && !part2Ok;
            if (part2Option.disabled && partSelect.value === '2') {
                partSelect.value = '';
            }
        }
        if (!isNc) {
            partSelect.value = '';
        }
        if (partHint) {
            partHint.hidden = !isNc || part2Ok;
        }
    }
    courseSelect.addEventListener('change', syncPracticePart);
    syncPracticePart();
});
